toolu_01LWdnp61PDGViefzMihbrKb.raw_arguments:
{"cmd":"cd /app; rm -rf /tmp/w; mkdir /tmp/w; 
mk(){ n=$1; mkdir /tmp/w/$n; cp -r shelfmark /tmp/w/$n/; (cd /tmp/w/$n; eval "$2"); }
mk utm "sed -i '19s/.*/        if name in cfg.ignore_params or name.startswith(\"utm_\"):/' shelfmark/keys.py"
mk loc "sed -i '38s/rng/loc/' shelfmark/locale.py"
mk purge "sed -i '23s/.*/        prefix = f\"{route}|{ident}|\"/' shelfmark/cache.py; sed -n 23,25p shelfmark/cache.py"
mk ttl "sed -i '39s/.*/        return int(value) * 1000/' shelfmark/config.py"
for n in utm loc purge ttl; do echo $n; python3 tools/replay.py --pkg /tmp/w/$n --diff | awk '$2>="2027-05-03T11:00:05" && /logged=miss replay=hit/' > /tmp/w/$n.out; wc -l < /tmp/w/$n.out; head -1 /tmp/w/$n.out; done
python3 tools/replay.py --diff | awk '$2>="2027-05-03T11:00:05"' | grep -v "logged=miss replay=miss" | head -5; python3 tools/replay.py --diff | tail -1"}

